import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/services/publication-support/journal-selection/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Journal Selection Service","serviceType":"Journal selection and manuscript submission support","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/publication-support/journal-selection/","description":"Journals chosen from your manuscript: scope fit, indexing in Scopus, Web of Science and PubMed, APCs compared, predatory titles screened out.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"},"hasOfferCatalog":{"@type":"OfferCatalog","name":"Journal selection packages","itemListElement":[{"@type":"Offer","name":"Standard — journal advice from a subject expert","description":"3–5 curated journal recommendations aligned to Scopus, SCI, PubMed and the right Web of Science collection (SCIE, SSCI, AHCI or ESCI), with a summary report and scope-fit rationale. Turnaround 4 working days. USD 130 per manuscript.","priceSpecification":{"@type":"PriceSpecification","price":"130","priceCurrency":"USD"}},{"@type":"Offer","name":"Advanced — selection plus manuscript preparation","description":"Everything in Standard, plus manuscript formatting to the selected journal guidelines and a drafted cover letter. Turnaround 7–8 working days."},{"@type":"Offer","name":"Elite — selection through to peer review","description":"Everything in Advanced, plus submission handling and tracking and peer-review rebuttal support through the first decision. Turnaround 10–12 working days."}]}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How do I choose the right journal for my research paper?","acceptedAnswer":{"@type":"Answer","text":"Match the manuscript’s scope, audience and methodology against the journal’s stated aims, then check what it has actually published in the last year. Confirm its indexing status and read the author guidelines in full before you commit. Most scope-based rejections are avoidable at this stage."}},{"@type":"Question","name":"How do I know if my manuscript fits a journal’s scope?","acceptedAnswer":{"@type":"Answer","text":"Read the aims and scope, then read recent issues. Compare your topic, design and methods against studies the journal has already accepted. If you cannot find a published paper that resembles yours in shape, the fit is probably weaker than the aims page suggests."}},{"@type":"Question","name":"What tools can help researchers find suitable journals?","acceptedAnswer":{"@type":"Answer","text":"Journal finder tools, Scopus and Web of Science searches, and citation analysis all help narrow a longlist. What they cannot do is judge whether your methodology will satisfy that journal’s reviewers, which is where a Pubrica subject expert is worth the time."}},{"@type":"Question","name":"What factors should I consider when selecting a journal?","acceptedAnswer":{"@type":"Answer","text":"Scope, audience, indexing status, impact and reputation, the peer-review process, time to decision, publication time, and the article processing charge. The right weighting between them depends on whether you are chasing a deadline, a grant requirement or maximum reach."}},{"@type":"Question","name":"How can I ensure my manuscript meets submission requirements?","acceptedAnswer":{"@type":"Answer","text":"Read the author guidelines and follow them exactly: structure, word count, reference style, figure formats and supplementary file rules. Editorial staff reject on formatting more often than authors expect, and it is the cheapest rejection to avoid."}},{"@type":"Question","name":"How can researchers identify reputable journals?","acceptedAnswer":{"@type":"Answer","text":"Check indexing in recognised databases, the publisher’s reputation, the editorial board, and whether the peer-review process is described transparently. A place in the Web of Science Core Collection is a signal in itself, since a journal only enters the Emerging Sources Citation Index after clearing Clarivate’s quality criteria for editorial rigour and publishing practice. If the journal promises acceptance in days, treat that as the answer."}},{"@type":"Question","name":"Can journal selection services improve acceptance chances?","acceptedAnswer":{"@type":"Answer","text":"Yes, by removing the commonest avoidable rejection. Matching a manuscript to a journal that publishes that kind of work does not make weak science strong, but it stops sound science being rejected for the wrong reason."}},{"@type":"Question","name":"How do I verify a journal’s credibility before submission?","acceptedAnswer":{"@type":"Answer","text":"Confirm database indexing — including which Web of Science collection the journal sits in, ESCI or a flagship index such as SCIE, SSCI or AHCI — then check the publisher and the named editorial board, read the stated peer-review policy, and look for a clear ethics and retraction policy. We screen every recommendation against predatory-journal indicators before it reaches you."}},{"@type":"Question","name":"What criteria do journals use to evaluate scope fit?","acceptedAnswer":{"@type":"Answer","text":"Relevance to the readership, alignment with the stated aims, methodological quality, originality, and how much the work adds to the field. An editor decides most of this within the first read of your abstract and cover letter."}},{"@type":"Question","name":"Why is selecting the right journal important?","acceptedAnswer":{"@type":"Answer","text":"It raises the chance of publication, puts the work in front of the audience that should act on it, and improves long-term visibility and citation. It also saves months: a scope rejection at journal one can cost a full submission cycle."}},{"@type":"Question","name":"When should researchers decide on a target journal?","acceptedAnswer":{"@type":"Answer","text":"Earlier than most do — ideally at the design stage. Knowing the target shapes the reporting guideline you follow, the structure you write to and the word count you work within, and it saves a rewrite later."}},{"@type":"Question","name":"Do you use AI to choose the journals?","acceptedAnswer":{"@type":"Answer","text":"No. Database queries and journal finder tools are used to build the longlist, which is what software is good at. The scoring, the shortlist and every reason written against a journal come from a Pubrica subject expert who publishes in your field. An algorithm can match your abstract to a topic; it cannot judge whether that journal’s reviewers will accept your methodology, which is the part that decides the outcome."}},{"@type":"Question","name":"Are you tied to a publisher?","acceptedAnswer":{"@type":"Answer","text":"No. A journal finder run by a publisher searches that publisher’s own portfolio first, because that is what it is for. Pubrica owns no journals, so Elsevier, Springer Nature, Wiley, Taylor & Francis, SAGE, society journals and regional titles are all assessed against the same criteria. If the best fit for your manuscript is a small society journal with a modest impact factor, that is what the report will say."}},{"@type":"Question","name":"What do you need from me to start?","acceptedAnswer":{"@type":"Answer","text":"The manuscript, or the title and abstract if it is not finished. Beyond that: the article type you intend to submit as, any indexing requirement you have to satisfy — Scopus, SCI, Web of Science, PubMed or the UGC-CARE list — your deadline, your article processing charge ceiling, and any journals you have already submitted to or want excluded. Nothing else is needed to begin, and everything you send is handled under GDPR."}},{"@type":"Question","name":"What happens if the recommended journal rejects my paper?","acceptedAnswer":{"@type":"Answer","text":"If the rejection is on scope — the journal says the work does not belong there — we reselect at no charge, because that is the judgement you paid us for. The same applies if a recommended title is later acquired by a predatory publisher. Rejection on the science, the methodology or the novelty is a different matter, and no selection service can insure against it; there we can tell you whether the reviewers’ objection is answerable and which of the remaining journals on the longlist it changes."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Publication support","item":"https://pubrica.com/services/publication-support/"},{"@type":"ListItem","position":3,"name":"Journal selection","item":"https://pubrica.com/services/publication-support/journal-selection/"}]}];

